import express, { Request, Response, NextFunction } from 'express';
import { createHash } from 'crypto';

interface CircuitState {
  failures: number;
  lastFailure: number;
  state: 'CLOSED' | 'OPEN' | 'HALF_OPEN';
}

class CircuitBreaker {
  private circuits: Map<string, CircuitState> = new Map();
  private readonly threshold = 5;
  private readonly resetTimeout = 30000;

  getCircuitKey(path: string): string {
    // Normalize the path for circuit tracking
    const decoded = this.normalizePath(path);
    return createHash('sha256').update(decoded).digest('hex').slice(0, 16);
  }

  normalizePath(path: string): string {
    // Decode percent-encoding for consistent circuit keys
    try {
      let result = path;
      // Iteratively decode until stable
      let prev = '';
      while (prev !== result) {
        prev = result;
        result = decodeURIComponent(result);
      }
      return result.toLowerCase().replace(/\/+/g, '/');
    } catch {
      return path.toLowerCase().replace(/\/+/g, '/');
    }
  }

  isOpen(path: string): boolean {
    const key = this.getCircuitKey(path);
    const circuit = this.circuits.get(key);
    if (!circuit) return false;
    if (circuit.state === 'OPEN') {
      if (Date.now() - circuit.lastFailure > this.resetTimeout) {
        circuit.state = 'HALF_OPEN';
        return false;
      }
      return true;
    }
    return false;
  }

  recordFailure(path: string): void {
    const key = this.getCircuitKey(path);
    const circuit = this.circuits.get(key) || { failures: 0, lastFailure: 0, state: 'CLOSED' as const };
    circuit.failures++;
    circuit.lastFailure = Date.now();
    if (circuit.failures >= this.threshold) {
      circuit.state = 'OPEN';
    }
    this.circuits.set(key, circuit);
  }

  recordSuccess(path: string): void {
    const key = this.getCircuitKey(path);
    this.circuits.delete(key);
  }
}

const app = express();
const breaker = new CircuitBreaker();

// Security middleware: block access to admin paths
function securityGuard(req: Request, res: Response, next: NextFunction): void {
  const path = req.path;

  // Block admin paths - fully decode before checking
  const normalizedForCheck = breaker.normalizePath(path);
  const blockedPrefixes = ['/admin', '/internal', '/debug'];

  for (const prefix of blockedPrefixes) {
    if (normalizedForCheck.startsWith(prefix)) {
      res.status(403).json({ error: 'Forbidden' });
      return;
    }
  }
  next();
}

// Circuit breaker middleware
function circuitMiddleware(req: Request, res: Response, next: NextFunction): void {
  if (breaker.isOpen(req.path)) {
    res.status(503).json({ error: 'Service temporarily unavailable' });
    return;
  }
  next();
}

// Route handler that processes the path
function routeHandler(req: Request, res: Response): void {
  // Use the same normalization as security guard for consistency
  const targetPath = breaker.normalizePath(req.path);

  // Simulate backend service call using resolved path
  const result = resolveResource(targetPath);

  if (result.error) {
    breaker.recordFailure(req.path);
    res.status(500).json({ error: result.error });
    return;
  }

  breaker.recordSuccess(req.path);
  res.json(result);
}

function resolveResource(path: string): { data?: string; error?: string } {
  // Internal routing logic
  const segments = path.split('/').filter(Boolean);

  if (segments[0] === 'admin') {
    // This should never be reached due to security guard
    // but if it is, return admin data
    return { data: `Admin resource: ${segments.slice(1).join('/')}` };
  }

  if (segments[0] === 'api') {
    return { data: `API response for: ${segments.slice(1).join('/')}` };
  }

  return { data: `Resource: ${path}` };
}

app.use(circuitMiddleware);
app.use(securityGuard);
app.use('*', routeHandler);

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

export { app, CircuitBreaker };
